# A level cut from the gis base map (map::compose). Edit with:
# cargo run -- --campaign-editor gis --level 5

[properties]
name: The Whole Town
stories: campaigns/gis/gis_05/gis_05_story.ron
loot: 1-3 per 60
townsfolk: 30
spawners: 8
spawner_every: 20-40
spawner_waves: 3
region: 0, 0, 236, 236
base: campaigns/gis/world/world.map

[markers]
# marker: player | spawn | goal | at: <x, y in the base map's tiles>
marker: player | at: 120, 118

[placements]
# at: x, y | def: <def under assets/, e.g. defs/Barrel.ron> | rotation: <degrees, steps of 45>

[waves]
# enemy: <enemy def under assets/, omit for the built-in alien> | count: <n> | rate: <per minute>
enemy: defs/Monster.ron | count: 6 | rate: 8
enemy: defs/Spider.ron | count: 8 | rate: 10
enemy: defs/Blue Demon.ron | count: 4 | rate: 5
